f (!root) return;\n\tconst elements = root.querySelectorAll(\"[data-i18n],[data-i18n-title],[data-i18n-placeholder],[data-i18n-aria-label]\");\n\tfor (const el of elements) {\n\t\tapplyStaticTranslation(el, el.getAttribute(\"data-i18n\"));\n\t\tapplyStaticTranslation(el, el.getAttribute(\"data-i18n-title\"), \"title\");\n\t\tapplyStaticTranslation(el, el.getAttribute(\"data-i18n-placeholder\"), \"placeholder\");\n\t\tapplyStaticTranslation(el, el.getAttribute(\"data-i18n-aria-label\"), \"aria-label\");\n\t}\n}\n","// ── Model store (signal-based) ──────────────────────────────\n//\n// Single source of truth for model data. Both Preact components\n// (auto-subscribe) and imperative code (read .value) can use this.\n\nimport { computed, signal } from \"@preact/signals\";\nimport { sendRpc } from \"../helpers\";\nimport type { ModelInfo, ReasoningSuffix, RpcResponse } from \"../types\";\n\nexport const REASONING_SEP = \"@reasoning-\";\n\n// ── Signals ──────────────────────────────────────────────────\nexport const models = signal<ModelInfo[]>([]);\nexport const selectedModelId = signal<string>(localStorage.getItem(\"moltis-model\") || \"\");\nexport const reasoningEffort = signal<string>(localStorage.getItem(\"moltis-reasoning-effort\") || \"\");\n\nexport const selectedModel = computed<ModelInfo | null>(() => {\n\tconst id = selectedModelId.value;\n\treturn models.value.find((m) => m.id === id) || null;\n});\n\n/** True when the currently selected model supports extended thinking. */\nexport const supportsReasoning = computed<boolean>(() => {\n\tconst m = selectedModel.value;\n\treturn !!(m && m.supportsReasoning);\n});\n\n/** Model ID with @reasoning-* suffix when effort is active. */\nexport const effectiveModelId = computed<string>(() => {\n\tconst id = selectedModelId.value;\n\tif (!id) return \"\";\n\tconst effort = reasoningEffort.value;\n\tif (effort && supportsReasoning.value) return id + REASONING_SEP + effort;\n\treturn id;\n});\n\n// ── Helpers ──────────────────────────────────────────────────\n\n/** Parse a model ID that may contain a @reasoning-* suffix.\n *  Returns { baseId, effort } where effort is \"\" if no suffix. */\nexport function parseReasoningSuffix(modelId: string): ReasoningSuffix {\n\tif (!modelId) return { baseId: \"\", effort: \"\" };\n\tconst idx = modelId.indexOf(REASONING_SEP);\n\tif (idx === -1) return { baseId: modelId, effort: \"\" };\n\treturn { baseId: modelId.substring(0, idx), effort: modelId.substring(idx + REASONING_SEP.length) };\n}\n\n/** True if a model ID is a @reasoning-* virtual variant. */\nexport function isReasoningVariant(modelId: string): boolean {\n\treturn modelId.indexOf(REASONING_SEP) !== -1;\n}\n\n// ── Methods ──────────────────────────────────────────────────\n\n/** Replace the full model list (e.g. after fetch or bootstrap). */\nexport function setAll(arr: ModelInfo[]): void {\n\tmodels.value = arr || [];\n}\n\n/** Fetch models from the server via RPC. */\nexport function fetch(): Promise<void> {\n\treturn sendRpc(\"models.list\", {}).then((r) => {\n\t\tconst res = r as RpcResponse<ModelInfo[]>;\n\t\tif (!res?.ok) return;\n\t\tsetAll(res.payload || []);\n\t\tif (models.value.length === 0) return;\n\t\tlet saved = localStorage.getItem(\"moltis-model\") || \"\";\n\t\t// If the saved model has a reasoning suffix, strip it and restore the effort\n\t\tconst parsed = parseReasoningSuffix(saved);\n\t\tif (parsed.effort) {\n\t\t\tsaved = parsed.baseId;\n\t\t\tsetReasoningEffort(parsed.effort);\n\t\t\tlocalStorage.setItem(\"moltis-model\", saved);\n\t\t}\n\t\tconst found = models.value.find((m) => m.id === saved);\n\t\tconst model = found || models.value[0];\n\t\tselect(model.id);\n\t\tif (!found) localStorage.setItem(\"moltis-model\", model.id);\n\t});\n}\n\n/** Select a model by id. Persists to localStorage. */\nexport function select(id: string): void {\n\tselectedModelId.value = id;\n}\n\n/** Set the reasoning effort level. Empty string means off. */\nexport function setReasoningEffort(effort: string): void {\n\treasoningEffort.value = effort || \"\";\n\tlocalStorage.setItem(\"moltis-reasoning-effort\", effort || \"\");\n}\n\n/** Look up a model by id. */\nexport function getById(id: string): ModelInfo | null {\n\treturn models.value.find((m) => m.id === id) || null;\n}\n\nexport const modelStore = {\n\tmodels,\n\tselectedModelId,\n\tselectedModel,\n\treasoningEffort,\n\tsupportsReasoning,\n\teffectiveModelId,\n\tparseReasoningSuffix,\n\tisReasoningVariant,\n\tsetAll,\n\tfetch,\n\tselect,\n\tsetReasoningEffort,\n\tgetById,\n};\n","// ── Project store (signal-based) ─────────────────────────────\n//\n// Single source of truth for project data and sidebar filter state.\n\nimport { signal } from \"@preact/signals\";\nimport { sendRpc } from \"../helpers\";\nimport type { ProjectInfo, RpcResponse } from \"../types\";\n\n// ── Signals ──────────────────────────────────────────────────\nexport const projects = signal<ProjectInfo[]>([]);\nexport const activeProjectId = signal<string>(localStorage.getItem(\"moltis-project\") || \"\");\nexport const projectFilterId = signal<string>(localStorage.getItem(\"moltis-project-filter\") || \"\");\n\n// ── Methods ──────────────────────────────────────────────────\n\n/** Replace the full project list (e.g. after fetch or bootstrap). */\nexport function setAll(arr: ProjectInfo[]): void {\n\tprojects.value = arr || [];\n}\n\n/** Fetch projects from the server via RPC. */\nexport function fetch(): Promise<void> {\n\treturn sendRpc(\"projects.list\", {}).then((r) => {\n\t\tconst res = r as RpcResponse<ProjectInfo[]>;\n\t\tif (!res?.ok) return;\n\t\tsetAll(res.payload || []);\n\t});\n}\n\n/** Set the active project id (bound to the active session's project). */\nexport function setActiveProjectId(id: string): void {\n\tactiveProjectId.value = id || \"\";\n}\n\n/** Set the sidebar filter project id. Persists to localStorage. */\nexport function setFilterId(id: string): void {\n\tprojectFilterId.value = id || \"\";\n\tif (id) {\n\t\tlocalStorage.setItem(\"moltis-project-filter\", id);\n\t} else {\n\t\tlocalStorage.removeItem(\"moltis-project-filter\");\n\t}\n}\n\n/** Look up a project by id. */\nexport function getById(id: string): ProjectInfo | null {\n\treturn projects.value.find((p) => p.id === id) || null;\n}\n\nexport const projectStore = {\n\tprojects,\n\tactiveProjectId,\n\tprojectFilterId,\n\tsetAll,\n\tfetch,\n\tsetActiveProjectId,\n\tsetFilterId,\n\tgetById,\n};\n","// ── Session store (signal-based) ─────────────────────────────\n//\n// Single source of truth for session data. Each session becomes a\n// Session class instance with per-session signals for client-side state.\n\nimport type { Signal } from \"@preact/signals\";\nimport { computed, signal } from \"@preact/signals\";\nimport type { ChannelBinding, SessionMeta, SessionTokens } from \"../types\";\n\n// ── Session class ────────────────────────────────────────────\n\nexport class Session {\n\t// Server fields (plain properties, set on construction/update)\n\tkey: string;\n\tlabel: string;\n\tmodel: string;\n\tprovider: string;\n\tprojectId: string;\n\tmessageCount: number;\n\tlastSeenMessageCount: number;\n\tpreview: string;\n\tupdatedAt: number;\n\tcreatedAt: number;\n\tworktree_branch: string;\n\tsandbox_enabled: boolean | undefined;\n\tsandbox_image: string | null;\n\tchannelBinding: ChannelBinding | null;\n\tparentSessionKey: string;\n\tforkPoint: number | null;\n\tagent_id: string;\n\tnode_id: string | null;\n\tmcpDisabled: boolean | undefined;\n\tarchived: boolean | undefined;\n\tactiveChannel: string | undefined;\n\tversion: number;\n\n\t// Client signals (reactive, per-session)\n\treplying: Signal<boolean>;\n\tlocalUnread: Signal<boolean>;\n\tstreamText: Signal<string>;\n\tvoicePending: Signal<boolean>;\n\tactiveRunId: Signal<string | null>;\n\tlastHistoryIndex: Signal<number>;\n\tsessionTokens: Signal<SessionTokens>;\n\tcontextWindow: Signal<number>;\n\ttoolsEnabled: Signal<boolean>;\n\tlast