ts read this to show/hide badge and compute unread tinting.\n\t\tthis.badgeCount = signal(this.messageCount);\n\t\t// Bumped whenever plain properties change so subscribed components re-render.\n\t\tthis.dataVersion = signal(0);\n\t}\n\n\t/** Recalculate badge from current messageCount. */\n\tupdateBadge(): void {\n\t\tthis.badgeCount.value = this.messageCount;\n\t}\n\n\t/** Merge server fields, preserving client signals. Returns false if stale. */\n\tupdate(serverData: SessionMeta): boolean {\n\t\tconst incoming = serverData.version || 0;\n\t\tif (incoming > 0 && this.version > 0 && incoming < this.version) return false;\n\t\tthis.version = incoming || this.version;\n\t\tthis.label = serverData.label || \"\";\n\t\tthis.model = serverData.model || \"\";\n\t\tthis.provider = serverData.provider || \"\";\n\t\tthis.projectId = serverData.projectId || \"\";\n\t\t// Only accept server counts when they've caught up with optimistic\n\t\t// client bumps. Authoritative resets (/clear, switchSession) use\n\t\t// syncCounts() which sets messageCount directly before any fetch.\n\t\tconst serverCount = serverData.messageCount || 0;\n\t\tif (serverCount >= this.messageCount) {\n\t\t\tthis.messageCount = serverCount;\n\t\t\tthis.lastSeenMessageCount = serverData.lastSeenMessageCount || 0;\n\t\t\tthis.preview = serverData.preview || \"\";\n\t\t\tthis.updatedAt = serverData.updatedAt || 0;\n\t\t}\n\t\tthis.createdAt = serverData.createdAt || 0;\n\t\tthis.worktree_branch = serverData.worktree_branch || \"\";\n\t\tthis.sandbox_enabled = serverData.sandbox_enabled;\n\t\tthis.sandbox_image = serverData.sandbox_image || null;\n\t\tthis.channelBinding = serverData.channelBinding || null;\n\t\tthis.parentSessionKey = serverData.parentSessionKey || \"\";\n\t\tthis.forkPoint = serverData.forkPoint != null ? serverData.forkPoint : null;\n\t\tthis.agent_id = serverData.agent_id || \"main\";\n\t\tthis.node_id = serverData.node_id || null;\n\t\tthis.mcpDisabled = serverData.mcpDisabled;\n\t\tthis.archived = serverData.archived;\n\t\tthis.activeChannel = serverData.activeChannel;\n\t\tthis.updateBadge();\n\t\tthis.dataVersion.value++;\n\t\treturn true;\n\t}\n\n\t/** Optimistic bump: increment total and mark seen if active. */\n\tbumpCount(increment: number): void {\n\t\tthis.messageCount = (this.messageCount || 0) + increment;\n\t\tif (this.key === activeSessionKey.value) {\n\t\t\tthis.lastSeenMessageCount = this.messageCount;\n\t\t}\n\t\tthis.updateBadge();\n\t}\n\n\t/** Authoritative set (switchSession history, /clear). */\n\tsyncCounts(messageCount: number, lastSeenMessageCount: number): void {\n\t\tthis.messageCount = messageCount;\n\t\tthis.lastSeenMessageCount = lastSeenMessageCount;\n\t\tthis.updateBadge();\n\t}\n\n\t/** Clear streaming state for this session. */\n\tresetStreamState(): void {\n\t\tthis.streamText.value = \"\";\n\t\tthis.voicePending.value = false;\n\t\tthis.activeRunId.value = null;\n\t\tthis.lastToolOutput.value = \"\";\n\t}\n}\n\n// ── Store signals ────────────────────────────────────────────\nexport const sessions = signal<Session[]>([]);\nexport const activeSessionKey = signal<string>(localStorage.getItem(\"moltis-session\") || \"main\");\nexport const switchInProgress = signal<boolean>(false);\nexport const refreshInProgressKey = signal<string>(\"\");\n/** Session list tab filter: \"all\" | \"sessions\" | \"cron\" */\nexport const sessionListTab = signal<string>(localStorage.getItem(\"moltis-session-tab\") || \"sessions\");\nexport const showArchivedSessions = signal<boolean>(localStorage.getItem(\"moltis-show-archived-sessions\") === \"1\");\n\nexport const activeSession = computed<Session | null>(() => {\n\tconst key = activeSessionKey.value;\n\treturn sessions.value.find((s) => s.key === key) || null;\n});\n\nexport function compareSessionOrder(left: Session | null, right: Session | null): number {\n\tconst leftKey = left?.key || \"\";\n\tconst rightKey = right?.key || \"\";\n\tconst leftMain = leftKey === \"main\";\n\tconst rightMain = rightKey === \"main\";\n\tif (leftMain !== rightMain) return leftMain ? -1 : 1;\n\n\tconst updatedDiff = (Number(right?.updatedAt) || 0) - (Number(left?.updatedAt) || 0);\n\tif (updatedDiff !== 0) return updatedDiff;\n\n\tconst createdDiff = (Number(right?.createdAt) || 0) - (Number(left?.createdAt) || 0);\n\tif (createdDiff !== 0) return createdDiff;\n\n\treturn leftKey.localeCompare(rightKey);\n}\n\nexport function insertSessionInOrder(list: Session[], session: Session): Session[] {\n\tif (!session?.key) return Array.isArray(list) ? list.slice() : [];\n\tconst result = Array.isArray(list) ? list.filter((entry) => entry?.key !== session.key) : [];\n\tresult.push(session);\n\tresult.sort(compareSessionOrder);\n\treturn result;\n}\n\n// ── Methods ──────────────────────────────────────────────────\n\n/**\n * Replace the full sessions list from server data.\n * Reuses existing Session instances (matched by key) so their\n * client-side signals (replying, localUnread, streamText) are preserved.\n * New keys get fresh instances. Missing keys are dropped.\n */\nexport function setAll(serverSessions: SessionMeta[]): void {\n\tconst existing: Record<string, Session> = {};\n\tfor (const s of sessions.value) {\n\t\texisting[s.key] = s;\n\t}\n\n\tconst result: Session[] = [];\n\tfor (const data of serverSessions) {\n\t\tconst prev = existing[data.key];\n\t\tif (prev) {\n\t\t\tprev.update(data);\n\t\t\t// Preserve client-side flags from old patched objects\n\t\t\tif (data._localUnread) prev.localUnread.value = true;\n\t\t\tif (data._replying || data.replying) prev.replying.value = true;\n\t\t\tresult.push(prev);\n\t\t} else {\n\t\t\tconst session = new Session(data);\n\t\t\tif (data._localUnread) session.localUnread.value = true;\n\t\t\tif (data._replying || data.replying) session.replying.value = true;\n\t\t\tresult.push(session);\n\t\t}\n\t}\n\n\tsessions.value = result;\n}\n\n/**\n * Upsert a single session from server data.\n * Reuses existing instance when present; creates and appends when missing.\n */\nexport function upsert(serverData: SessionMeta): Session | null {\n\tif (!serverData?.key) return null;\n\tconst prev = getByKey(serverData.key);\n\tif (prev) {\n\t\tprev.update(serverData);\n\t\tsessions.value = insertSessionInOrder(sessions.value, prev);\n\t\treturn prev;\n\t}\n\tconst next = new Session(serverData);\n\tsessions.value = insertSessionInOrder(sessions.value, next);\n\treturn next;\n}\n\n/** Remove a session by key. Returns true when a session was removed. */\nexport function remove(key: string): boolean {\n\tif (!key) return false;\n\tconst existing = getByKey(key);\n\tif (!existing) return false;\n\tsessions.value = sessions.value.filter((session) => session.key !== key);\n\tif (activeSessionKey.value === key) {\n\t\tconst fallback = sessions.value.find((session) => session.key === \"main\")?.key || sessions.value[0]?.key || \"main\";\n\t\tactiveSessionKey.value = fallback;\n\t\tlocalStorage.setItem(\"moltis-session\", fallback);\n\t}\n\treturn true;\n}\n\n/** Fetch sessions from the server via HTTP (gzip-friendly). */\nexport function fetch(): Promise<void> {\n\treturn window\n\t\t.fetch(\"/api/sessions\", {\n\t\t\theaders: { Accept: \"application/json\" },\n\t\t})\n\t\t.then((response) => (response.ok ? response.json() : null))\n\t\t.then((payload: SessionMeta[] | null) => {\n\t\t\tif (!Array.isArray(payload)) return;\n\t\t\tsetAll(payload);\n\t\t})\n\t\t.catch(() => {});\n}\n\n/** Notify Preact that session data changed (triggers re-render). */\nexport function notify(): void {\n\tsessions.value = [...sessions.value];\n}\n\n/** Look up a session by key. */\nexport function getByKey(key: string): Session | null {\n\treturn sessions.value.find((s) => s.key === key) || null;\n}\n\n/** Set the active session key. Persists to localStorage. */\nexport function setActive(key: string): void {\n\tactiveSessionKey.value = key;\n\tlocalStorage.setItem(\"moltis-session\", key);\n}\n\n/** Set the session list tab and persist it. */\nexport function setSessionListTab(tab: string): void {\n\tsessionListTab.value = tab;\n\tlocalStorage.setItem(\"moltis-session-tab\", tab);\n}\n\n/** Toggle whether archived sessions are shown in the sidebar. */\nexport function setShowArchivedSessions(show: boolean): void {\n\tshowArchivedSessions.value = !!show;\n\tlocalStorage.setItem(\"moltis-show-archived-sessions\", show ? \"1\" : \"0\");\n}\n\nexport const sessionStore = {\n\tsessions,\n\tactiveSessionKey,\n\tactiveSession,\n\tswitchInProgress,\n\trefreshInProgressKey,\n\tsessionListTab,\n\tshowArchivedSessions,\n\tSession,\n\tsetAll,\n\tupsert,\n\tremove,\n\tfetch,\n\tgetByKey,\n\tsetActive,\n\tsetSessionListTab,\n\tsetShowArchivedSessions,\n\tnotify,\n};\n","// ── Preact signal bridge for shared state ─────────────────────\n// Mirrors key state.js vars as Preact signals so that both imperative\n// code (websocket.js) and Preact pages can coexist during migration.\n//\n// Signals for models, projects, sessions, selectedModelId, and\n// activeSessionKey have moved to stores/*.js. They are re-exported\n// here for backward compat with pages that still import from signals.js.\n\nimport type { Signal } from \"@preact/signals\";\nimport { signal } from \"@preact/signals\";\nimport { models, selectedModelId } from \"./stores/model-store\";\nimport { projects } from \"./stores/project-store\";\nimport { activeSessionKey, sessions } from \"./stores/session-store\";\n\nexport { activeSessionKey, models, projects, selectedModelId, sessions };\n\n// Signals that haven't moved to stores yet\nexport const connected: Signal<boolean> = signal(false);\nexport const cachedChannels: Signal<unknown | null> = signal(null);\nexport const unseenErrors: Signal<number> = signal(0);\nexport const unseenWarns: Signal<number> = signal(0);\nexport const sandboxInfo: Signal<unknown | null> = signal(null);\n","// ── Shared mutable state ────────────────────────────────────\n\nimport * as sig from \"./signals\";\nimport type { RpcResponse, SessionTokens } from \"./types\";\n\nexport let ws: WebSocket | null = null;\nexport let reqId = 0;\nexport let connected = false;\nexport let subscribed = false;\nexport let reconnectDelay = 1000;\nexport const pending: Record<string, (value: RpcResponse) => void> = {};\nexport let models: unknown[] = [];\nexport let activeSessionKey: string = localStorage.getItem(\"moltis-session\") || \"main\";\nexport let activeProjectId: string = localStorage.getItem(\"moltis-project\") || \"\";\nexport let sessions: unknown[] = [];\nexport let projects: unknown[] = [];\n\n// Chat-page specific state (persists across page transitions)\nexport let streamEl: HTMLElement | null = null;\nexport let streamText = \"\";\nexport let lastToolOutput = \"\";\nexport let voicePending = false;\nexport let chatHistory: string[] = JSON.parse(localStorage.getItem(\"moltis-chat-history\") || \"[]\");\nexport let chatHistoryIdx = -1;\nexport let chatHistoryDraft = \"\";\n// Client-side sequence counter for message ordering diagnostics.\n// Resumed from the highest user seq in history on session switch.\nexport let chatSeq = 0;\n\n// Session token usage tracking (cumulative for the current session)\nexport let sessionTokens: SessionTokens = { input: 0, output: 0 };\n// Last observed prompt input tokens (context pressure for the next turn).\nexport let sessionCurrentInputTokens = 0;\n\n// Model selector elements — created dynamically inside the chat page\nexport let modelCombo: HTMLElement | null = null;\nexport let modelComboBtn: HTMLElement | null = null;\nexport let modelComboLabel: HTMLElement | null = null;\nexport let modelDropdown: HTMLElement | null = null;\nexport let modelSearchInput: HTMLElement | null = null;\nexport let modelDropdownList: HTMLElement | null = null;\nexport let selectedModelId: string = localStorage.getItem(\"moltis-model\") || \"\";\nexport let modelIdx = -1;\n\n// Node selector elements — created dynamically inside the chat page\nexport let nodeCombo: HTMLElement | null = null;\nexport let nodeComboBtn: HTMLElement | null = null;\nexport let nodeComboLabel: HTMLElement | null = null;\nexport let nodeDropdown: HTMLElement | null = null;\nexport let nodeDropdownList: HTMLElement | null = null;\n\n// Session project combo (in chat header)\nexport let projectCombo: HTMLElement | null = null;\nexport let projectComboBtn: HTMLElement | null = null;\nexport let projectComboLabel: HTMLElement | null = null;\nexport let projectDropdown: HTMLElement | null = null;\nexport let projectDropdownList: HTMLElement | null = null;\n\n// Sandbox toggle\nexport let sandboxToggleBtn: HTMLElement | null = null;\nexport let sandboxLabel: HTMLElement | null = null;\nexport let sessionSandboxEnabled = true;\nexport let sessionSandboxImage: string | null = null;\nexport let sandboxImageBtn: HTMLElement | null = null;\nexport let sandboxImageDropdown: HTMLElement | null = null;\nexport let sandboxImageLabel: HTMLElement | null = null;\n\n// Chat page DOM refs\nexport let chatMsgBox: HTMLElement | null = null;\nexport let chatInput: HTMLElement | null = null;\nexport let chatSendBtn: HTMLElement | null = null;\nexport let chatBatchLoading = false;\nexport let sessionSwitchInProgress = false;\n// Highest message index loaded from session history; used to deduplicate\n// real-time events that duplicate already-rendered history entries.\nexport let lastHistoryIndex = -1;\nexport let sessionContextWindow = 0;\nexport let sessionToolsEnabled = true;\nexport let sessionExecMode = \"host\";\nexport let sessionExecPromptSymbol = \"$\";\nexport let hostExecIsRoot = false;\nexport let commandModeEnabled = false;\n\n// Provider/channel page refresh callbacks\nexport let refreshProvidersPage: (() => void) | null = null;\nexport let refreshChannelsPage: (() => void) | null = null;\nexport let channelEventUnsub: (() => void) | null = null;\n\n// Prefetched channel data\nexport let cachedChannels: unknown | null = null;\nexport function setCachedChannels(v: unknown | null): void {\n\tcachedChannels = v;\n\tsig.cachedChannels.value = v;\n}\n\n// Sandbox\nexport let sandboxInfo: unknown | null = null;\n\n// Logs\nexport let logsEventHandler: ((payload?: unknown) => void) | null = null;\n\n// Network audit\nexport let networkAuditEventHandler: ((payload?: unknown) => void) | null = null;\nexport let unseenErrors = 0;\nexport let unseenWarns = 0;\n\n// Project filter\nexport let projectFilterId: string = localStorage.getItem(\"moltis-project-filter\") || \"\";\n\n// DOM shorthand\nexport function $(id: string): HTMLElement | null {\n\treturn document.getElementById(id);\n}\n\n// ── Setters ──────────────────────────────────────────────────\nexport function setWs(v: WebSocket | null): void {\n\tws = v;\n}\nexport function setReqId(v: number): void {\n\treqId = v;\n}\nexport function setConnected(v: boolean): void {\n\tconnected = v;\n\tsig.connected.value = v;\n}\nexport function setSubscribed(v: boolean): void {\n\tsubscribed = v;\n}\nexport function setReconnectDelay(v: number): void {\n\treconnectDelay = v;\n}\nexport function setModels(v: unknown[]): void {\n\tmodels = v;\n\t// Store signal is now owned by model-store.ts; don't overwrite here.\n}\nexport function setActiveSessionKey(v: string): void {\n\tactiveSessionKey = v;\n\t// Store signal is now owned by session-store.ts; don't overwrite here.\n}\nexport function setActiveProjectId(v: string): void {\n\tactiveProjectId = v;\n}\nexport function setSessions(v: unknown[]): void {\n\tsessions = v;\n\t// Store signal is now owned by session-store.ts; don't overwrite here.\n}\nexport function setProjects(v: unknown[]): void {\n\tprojects = v;\n\t// Store signal is now owned by project-store.ts; don't overwrite here.\n}\nexport function setStreamEl(v: HTMLElement | null): void {\n\tstreamEl = v;\n}\nexport function setStreamText(v: string): void {\n\tstreamText = v;\n}\nexport function setLastToolOutput(v: string): void {\n\tlastToolOutput = v;\n}\nexport function setVoicePending(v: boolean): void {\n\tvoicePending = v;\n}\nexport function setChatHistory(v: string[]): void {\n\tchatHistory = v;\n}\nexport function setChatHistoryIdx(v: number): void {\n\tchatHistoryIdx = v;\n}\nexport function setChatHistoryDraft(v: string): void {\n\tchatHistoryDraft = v;\n}\nexport function setChatSeq(v: number): void {\n\tchatSeq = v;\n}\nexport function setSessionTokens(v: SessionTokens): void {\n\tsessionTokens = v;\n}\nexport function setSessionCurrentInputTokens(v: number): void {\n\tsessionCurrentInputTokens = v;\n}\nexport function setModelCombo(v: HTMLElement | null): void {\n\tmodelCombo = v;\n}\nexport function setModelComboBtn(v: HTMLElement | null): void {\n\tmodelComboBtn = v;\n}\nexport function setModelComboLabel(v: HTMLElement | null): void {\n\tmodelComboLabel = v;\n}\nexport function setModelDropdown(v: HTMLElement | null): void {\n\tmodelDropdown = v;\n}\nexport function setModelSearchInput(v: HTMLElement | null): void {\n\tmodelSearchInput = v;\n}\nexport function setModelDropdownList(v: HTMLElement | null): void {\n\tmodelDropdownList = v;\n}\nexport function setSelectedModelId(v: string): void {\n\tselectedModelId = v;\n\t// Store signal is now owned by model-store.ts; don't overwrite here.\n}\nexport function setModelIdx(v: number): void {\n\tmodelIdx = v;\n}\nexport function setNodeCombo(v: HTMLElement | null): void {\n\tnodeCombo = v;\n}\nexport function setNodeComboBtn(v: HTMLElement | null): void {\n\tnodeComboBtn = v;\n}\nexport function setNodeComboLabel(v: HTMLElement | null): void {\n\tnodeComboLabel = v;\n}\nexport function setNodeDropdown(v: HTMLElement | null): void {\n\tnodeDropdown = v;\n}\nexport function setNodeDropdownList(v: HTMLElement | null): void {\n\tnodeDropdownList = v;\n}\nexport function setProjectCombo(v: HTMLElement | null): void {\n\tprojectCombo = v;\n}\nexport function setProjectComboBtn(v: HTMLElement | null): void {\n\tprojectComboBtn = v;\n}\nexport function setProjectComboLabel(v: HTMLElement | null): void {\n\tprojectComboLabel = v;\n}\nexport function setProjectDropdown(v: HTMLElement | null): void {\n\tprojectDropdown = v;\n}\nexport function setProjectDropdownList(v: HTMLElement | null): void {\n\tprojectDropdownList = v;\n}\nexport function setSandboxToggleBtn(v: HTMLElement | null): void {\n\tsandboxToggleBtn = v;\n}\nexport function setSandboxLabel(v: HTMLElement | null): void {\n\tsandboxLabel = v;\n}\nexport function setSessionSandboxEnabled(v: boolean): void {\n\tsessionSandboxEnabled = v;\n}\nexport function setSessionSandboxImage(v: string | null): void {\n\tsessionSandboxImage = v;\n}\nexport function setSandboxImageBtn(v: HTMLElement | null): void {\n\tsandboxImageBtn = v;\n}\nexport function setSandboxImageDropdown(v: HTMLElement | null): void {\n\tsandboxImageDropdown = v;\n}\nexport function setSandboxImageLabel(v: HTMLElement | null): void {\n\tsandboxImageLabel = v;\n}\nexport function setChatMsgBox(v: HTMLElement | null): void {\n\tchatMsgBox = v;\n}\nexport function setChatInput(v: HTMLElement | null): void {\n\tchatInput = v;\n}\nexport function setChatSendBtn(v: HTMLElement | null): void {\n\tchatSendBtn = v;\n}\nexport function setChatBatchLoading(v: boolean): void {\n\tchatBatchLoading = v;\n}\nexport function setSessionSwitchInProgress(v: boolean): void {\n\tsessionSwitchInProgress = v;\n}\nexport function setLastHistoryIndex(v: number): void {\n\tlastHistoryIndex = v;\n}\nexport function setSessionContextWindow(v: number): void {\n\tsessionContextWindow = v;\n}\nexport function setSessionToolsEnabled(v: boolean): void {\n\tsessionToolsEnabled = v;\n}\nexport function setSessionExecMode(v: string): void {\n\tsessionExecMode = v;\n}\nexport function setSessionExecPromptSymbol(v: string): void {\n\tsessionExecPromptSymbol = v;\n}\nexport function setHostExecIsRoot(v: boolean): void {\n\thostExecIsRoot = !!v;\n}\nexport function setCommandModeEnabled(v: boolean): void {\n\tcommandModeEnabled = !!v;\n}\nexport function setRefreshProvidersPage(v: (() => void) | null): void {\n\trefreshProvidersPage = v;\n}\nexport function setRefreshChannelsPage(v: (() => void) | null): void {\n\trefreshChannelsPage = v;\n}\nexport function setChannelEventUnsub(v: (() => void) | null): void {\n\tchannelEventUnsub = v;\n}\nexport function setLogsEventHandler(v: ((payload?: unknown) => void) | null): void {\n\tlogsEventHandler = v;\n}\nexport function setNetworkAuditEventHandler(v: ((payload?: unknown) => void) | null): void {\n\tnetworkAuditEventHandler = v;\n}\nexport function setUnseenErrors(v: number): void {\n\tunseenErrors = v;\n\tsig.unseenErrors.value = v;\n}\nexport function setUnseenWarns(v: number): void {\n\tunseenWarns = v;\n\tsig.unseenWarns.value = v;\n}\nexport function setProjectFilterId(v: string): void {\n\tprojectFilterId = v;\n}\nexport function setSandboxInfo(v: unknown | null): void {\n\tsandboxInfo = v;\n\tsig.sandboxInfo.value = v;\n}\n","// ── Helpers ──────────────────────────────────────────────────\nimport { hasTranslation, t } from \"./i18n\";\nimport * as S from \"./state\";\nimport type { RpcResponse } from \"./types\";\nimport type { RpcMethod, RpcMethodMap } from \"./types/rpc-methods\";\n\n// Extend Window for webkitAudioContext (Safari)\ndeclare global {\n\tinterface Window {\n\t\twebkitAudioContext?: typeof AudioContext;\n\t}\n}\n\ninterface CodeBlock {\n\tlang: string;\n\tcode: string;\n}\n\ninterface TableParseResult {\n\thtml: string;\n\tnext: number;\n}\n\ninterface ParsedError {\n\ticon: string;\n\ttitle: string;\n\tdetail: string;\n\tresetsAt: number | null;\n\tprovider?: string;\n}\n\ninterface StructuredError {\n\ticon?: string;\n\ttitle?: string;\n\tdetail?: string;\n\tmessage?: string;\n\tprovider?: string;\n\tresetsAt?: number | null;\n\ttitle_key?: string;\n\tdetail_key?: string;\n\ttitle_params?: Record<string, unknown>;\n\tdetail_params?: Record<string, unknown>;\n}\n\ninterface RpcErrorObj {\n\tcode?: string;\n\tmessage?: string;\n\tserverMessage?: string;\n}\n\ninterface LocalizedRpcError extends RpcErrorObj {\n\tserverMessage?: string;\n}\n\ninterface ApiPayload {\n\terror?: string | RpcErrorObj;\n\tcode?: string;\n\tmessage?: string;\n}\n\ninterface ToolCallArgs {\n\tcommand?: string;\n\tnode?: string;\n\turl?: string;\n\tquery?: string;\n\taction?: string;\n\t[key: string]: unknown;\n}\n\ninterface MapLinks {\n\turl?: string;\n\tgoogle_maps?: string;\n\tapple_maps?: string;\n\topenstreetmap?: string;\n\t[key: string]: unknown;\n}\n\ninterface MapPoint {\n\tlabel?: string;\n\tlatitude?: number;\n\tlongitude?: number;\n\tmap_links?: MapLinks;\n}\n\ninterface AgentEntry {\n\tid?: string;\n\tis_default?: boolean;\n\t[key: string]: unknown;\n}\n\ninterface AgentsListPayload {\n\tdefault_id?: string;\n\tagents?: AgentEntry[];\n}\n\ninterface ParsedAgentsList {\n\tdefaultId: string;\n\tagents: AgentEntry[];\n}\n\ninterface CreateElAttrs {\n\tclassName?: string;\n\ttextContent?: string;\n\tstyle?: string;\n\t[key: string]: string | undefined;\n}\n\n/**\n * Extract the highest version number from a model ID for sorting.\n * e.g. \"gpt-5.4-mini\" -> 5.4, \"claude-opus-4-6-20260301\" -> 20260301, \"o4-mini\" -> 4\n * For models with a date suffix the date itself becomes the sort key, which is\n * intentional -- newer dates rank higher.  Returns 0 when no number is found.\n */\nexport function modelVersionScore(id: string): number {\n\tconst matches = (id || \"\").match(/\\d+(?:\\.\\d+)?/g);\n\tif (!matches) return 0;\n\tlet max = 0;\n\tfor (const m of matches) {\n\t\tconst v = Number.parseFloat(m);\n\t\tif (v > max) max = v;\n\t}\n\treturn max;\n}\n\nfunction translatedOrFallback(\n\tkey: string | undefined,\n\topts: Record<string, unknown> | undefined,\n\tfallback: string,\n): string {\n\tif (!key) return fallback;\n\tif (!hasTranslation(key, opts)) return fallback;\n\tconst translated = t(key, opts);\n\tif (translated) return translated;\n\treturn fallback;\n}\n\nexport function nextId(): string {\n\tS.setReqId(S.reqId + 1);\n\treturn `ui-${S.reqId}`;\n}\n\nexport function esc(s: string): string {\n\treturn s.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\");\n}\n\nfunction stripAnsi(text: string | null | undefined): string {\n\tconst input = String(text || \"\");\n\tlet out = \"\";\n\tfor (let i = 0; i < input.length; i++) {\n\t\tif (input.charCodeAt(i) === 27 && input[i + 1] === \"[\") {\n\t\t\ti += 2;\n\t\t\twhile (i < input.length) {\n\t\t\t\tconst ch = input[i];\n\t\t\t\tif (ch >= \"@\" && ch <= \"~\") break;\n\t\t\t\ti++;\n\t\t\t}\n\t\t\tcontinue;\n\t\t}\n\t\tout += input[i];\n\t}\n\treturn out;\n}\n\nfunction splitPipeCells(line: string): string[] {\n\tlet plain = stripAnsi(line).trim();\n\tif (plain.startsWith(\"|\")) plain = plain.slice(1);\n\tif (plain.endsWith(\"|\")) plain = plain.slice(0, -1);\n\treturn plain.split(\"|\").map((cell) => cell.trim());\n}\n\nfunction normalizeTableRow(cells: string[], columnCount: number): string[] {\n\tconst row = cells.slice(0, columnCount);\n\twhile (row.length < columnCount) row.push(\"\");\n\treturn row;\n}\n\nfunction buildTableHtml(headerCells: string[], bodyRows: string[][]): string {\n\tconst columnCount = headerCells.length;\n\tconst headerRow = normalizeTableRow(headerCells, columnCount);\n\tconst bodyHtml = bodyRows\n\t\t.map((row) => normalizeTableRow(row, columnCount))\n\t\t.map((row) => `<tr>${row.map((cell) => `<td>${cell}</td>`).join(\"\")}</tr>`)\n\t\t.join(\"\");\n\tconst thead = `<thead><tr>${headerRow.map((cell) => `<th>${cell}</th>`).join(\"\")}</tr></thead>`;\n\tconst tbody = bodyRows.length > 0 ? `<tbody>${bodyHtml}</tbody>` : \"\";\n\treturn `<div class=\"msg-table-wrap\"><table class=\"msg-table\">${thead}${tbody}</table></div>`;\n}\n\nfunction isMarkdownPipeRow(line: string): boolean {\n\tif (!stripAnsi(line).includes(\"|\")) return false;\n\treturn splitPipeCells(line).length >= 2;\n}\n\nfunction isMarkdownSeparatorRow(line: string, expectedCols: number): boolean {\n\tconst cells = splitPipeCells(line);\n\tif (cells.length !== expectedCols) return false;\n\treturn cells.every((cell) => /^:?-{3,}:?$/.test(cell));\n}\n\nfunction parseMarkdownTable(lines: string[], start: number): TableParseResult | null {\n\tif (start + 1 >= lines.length) return null;\n\tif (!isMarkdownPipeRow(lines[start])) return null;\n\tconst headerCells = splitPipeCells(lines[start]);\n\tif (headerCells.length < 2) return null;\n\tif (!isMarkdownSeparatorRow(lines[start + 1], headerCells.length)) return null;\n\n\tconst bodyRows: string[][] = [];\n\tlet next = start + 2;\n\twhile (next < lines.length) {\n\t\tconst candidate = lines[next];\n\t\tif (!candidate.trim()) break;\n\t\tif (!isMarkdownPipeRow(candidate)) break;\n\t\tbodyRows.push(splitPipeCells(candidate));\n\t\tnext++;\n\t}\n\treturn {\n\t\thtml: buildTableHtml(headerCells, bodyRows),\n\t\tnext: next,\n\t};\n}\n\nfunction isAsciiBorderRow(line: string): boolean {\n\treturn /^\\+(?:[-=]+\\+)+$/.test(stripAnsi(line).trim());\n}\n\nfunction isAsciiPipeRow(line: string): boolean {\n\treturn /^\\|.*\\|$/.test(stripAnsi(line).trim());\n}\n\nfunction parseAsciiTable(lines: string[], start: number): TableParseResult | null {\n\tif (!isAsciiBorderRow(lines[start])) return null;\n\tlet next = start + 1;\n\tconst rows: string[][] = [];\n\n\twhile (next < lines.length) {\n\t\tconst line = lines[next];\n\t\tif (isAsciiBorderRow(line)) {\n\t\t\tnext++;\n\t\t\tcontinue;\n\t\t}\n\t\tif (!isAsciiPipeRow(line)) break;\n\t\trows.push(splitPipeCells(line));\n\t\tnext++;\n\t}\n\tif (rows.length === 0) return null;\n\n\treturn {\n\t\thtml: buildTableHtml(rows[0], rows.slice(1)),\n\t\tnext: next,\n\t};\n}\n\nfunction renderTables(s: string): string {\n\tconst lines = s.split(\"\\n\");\n\tconst out: string[] = [];\n\tfor (let i = 0; i < lines.length; ) {\n\t\tconst markdownTable = parseMarkdownTable(lines, i);\n\t\tif (markdownTable) {\n\t\t\tout.push(markdownTable.html);\n\t\t\ti = markdownTable.next;\n\t\t\tcontinue;\n\t\t}\n\n\t\tconst asciiTable = parseAsciiTable(lines, i);\n\t\tif (asciiTable) {\n\t\t\tout.push(asciiTable.html);\n\t\t\ti = asciiTable.next;\n\t\t\tcontinue;\n\t\t}\n\n\t\tout.push(lines[i]);\n\t\ti++;\n\t}\n\treturn out.join(\"\\n\");\n}\n\nexport function renderMarkdown(raw: string): string {\n\tlet s = esc(raw);\n\tconst codeBlocks: CodeBlock[] = [];\n\ts = s.replace(/```(\\w*)\\n([\\s\\S]*?)```/g, (_: string, lang: string, code: string) => {\n\t\tcodeBlocks.push({ lang: lang, code: code });\n\t\treturn `@@MOLTIS_CODE_BLOCK_${codeBlocks.length - 1}@@`;\n\t});\n\ts = renderTables(s);\n\ts = s.replace(/`([^`]+)`/g, \"<code>$1</code>\");\n\ts = s.replace(/\\*\\*(.+?)\\*\\*/g, \"<strong>$1</strong>\");\n\ts = s.replace(/@@MOLTIS_CODE_BLOCK_(\\d+)@@/g, (_: string, idx: string) => {\n\t\tconst block = codeBlocks[Number(idx)];\n\t\tif (!block) return \"\";\n\t\tconst langAttr = block.lang ? ` data-lang=\"${block.lang}\"` : \"\";\n\t\tconst badge = block.lang ? `<div class=\"code-lang-badge\">${block.lang}</div>` : \"\";\n\t\treturn `<pre class=\"code-block\">${badge}<code${langAttr}>${block.code}</code></pre>`;\n\t});\n\treturn s;\n}\n\nexport function sendRpc<M extends RpcMethod>(\n\tmethod: M,\n\tparams: Record<string, unknown> | unknown,\n): Promise<RpcResponse<RpcMethodMap[M]>>;\nexport function sendRpc<T = unknown>(method: string, params: unknown): Promise<RpcResponse<T>>;\nexport function sendRpc(method: string, params: unknown): Promise<RpcResponse> {\n\treturn new Promise((resolve) => {\n\t\tif (!S.ws || S.ws.readyState !== WebSocket.OPEN) {\n\t\t\tresolve({\n\t\t\t\tok: false,\n\t\t\t\terror: {\n\t\t\t\t\tcode: \"UNAVAILABLE\",\n\t\t\t\t\tmessage: localizedRpcErrorMessage({\n\t\t\t\t\t\tcode: \"UNAVAILABLE\",\n\t\t\t\t\t\tmessage: \"WebSocket not connected\",\n\t\t\t\t\t}),\n\t\t\t\t},\n\t\t\t});\n\t\t\treturn;\n\t\t}\n\t\tconst id = nextId();\n\t\tS.pending[id] = resolve as (value: RpcResponse) => void;\n\t\tS.ws.send(JSON.stringify({ type: \"req\", id: id, method: method, params: params }));\n\t});\n}\n\nexport function localizedRpcErrorMessage(error: RpcErrorObj | null | undefined): string {\n\tif (!error) return t(\"errors:generic.title\");\n\tif (error.code) {\n\t\tconst key = `errors:codes.${error.code}`;\n\t\tconst translated = t(key);\n\t\tif (translated && translated !== key) {\n\t\t\treturn translated;\n\t\t}\n\t}\n\treturn error.message || t(\"errors:generic.title\");\n}\n\nexport function localizedApiErrorMessage(payload: ApiPayload | null | undefined, fallbackMessage?: string): string {\n\tif (payload && typeof payload.error === \"object\") {\n\t\treturn localizedRpcErrorMessage(payload.error);\n\t}\n\tif (payload?.code) {\n\t\tconst key = `errors:codes.${payload.code}`;\n\t\tconst translated = t(key);\n\t\tif (translated && translated !== key) {\n\t\t\treturn translated;\n\t\t}\n\t}\n\tif (payload && typeof payload.error === \"string\" && payload.error.trim()) {\n\t\treturn payload.error;\n\t}\n\tif (payload && typeof payload.message === \"string\" && payload.message.trim()) {\n\t\treturn payload.message;\n\t}\n\treturn fallbackMessage || t(\"errors:generic.title\");\n}\n\nexport function localizeRpcError(error: RpcErrorObj | null | undefined): LocalizedRpcError | null | undefined {\n\tif (!error) return error;\n\t// When the server provides a specific message (not just an error code),\n\t// preserve it as `serverMessage` so callers like model probes can show\n\t// the precise backend reason instead of a generic locale string.\n\tconst message = localizedRpcErrorMessage(error);\n\tif (error.message === message) return error;\n\treturn Object.assign({}, error, { message: message, serverMessage: error.message });\n}\n\nexport function localizeStructuredError(error: StructuredError | null | undefined): StructuredError | null | undefined {\n\tif (!error) return error;\n\tconst title = translatedOrFallback(error.title_key, error.title_params, error.title || t(\"errors:generic.title\"));\n\tconst detail = translatedOrFallback(error.detail_key, error.detail_params, error.detail || \"\");\n\tif (title === error.title && detail === (error.detail || \"\")) return error;\n\treturn Object.assign({}, error, { title: title, detail: detail });\n}\n\nexport function formatTokens(n: number): string {\n\tif (n >= 1000000) return `${(n / 1000000).toFixed(1)}M`;\n\tif (n >= 1000) return `${(n / 1000).toFixed(1)}K`;\n\treturn String(n);\n}\n\nexport function formatAssistantTokenUsage(\n\tinputTokens: number | undefined,\n\toutputTokens: number | undefined,\n\tcacheReadTokens?: number | undefined,\n): string {\n\tconst input = Number(inputTokens || 0);\n\tconst output = Number(outputTokens || 0);\n\tconst cached = Number(cacheReadTokens || 0);\n\tlet inputText = `${formatTokens(input)} in`;\n\tif (cached > 0) {\n\t\tinputText += ` (${formatTokens(cached)} cached)`;\n\t}\n\treturn `${inputText} / ${formatTokens(output)} out`;\n}\n\nconst TOKEN_SPEED_SLOW_TPS = 10;\nconst TOKEN_SPEED_FAST_TPS = 25;\n\nexport function tokenSpeedPerSecond(outputTokens: number | undefined, durationMs: number | undefined): number | null {\n\tconst out = Number(outputTokens || 0);\n\tconst ms = Number(durationMs || 0);\n\tif (!(out > 0 && ms > 0)) return null;\n\tconst speed = (out * 1000) / ms;\n\treturn Number.isFinite(speed) && speed > 0 ? speed : null;\n}\n\nexport function formatTokenSpeed(outputTokens: number | undefined, durationMs: number | undefined): string | null {\n\tconst speed = tokenSpeedPerSecond(outputTokens, durationMs);\n\tif (speed == null) return null;\n\tif (speed >= 100) return `${speed.toFixed(0)} tok/s`;\n\tif (speed >= 10) return `${speed.toFixed(1)} tok/s`;\n\treturn `${speed.toFixed(2)} tok/s`;\n}\n\nexport function tokenSpeedTone(outputTokens: number | undefined, durationMs: number | undefined): string | null {\n\tconst speed = tokenSpeedPerSecond(outputTokens, durationMs);\n\tif (speed == null) return null;\n\tif (speed < TOKEN_SPEED_SLOW_TPS) return \"slow\";\n\tif (speed >= TOKEN_SPEED_FAST_TPS) return \"fast\";\n\treturn \"normal\";\n}\n\nexport function formatBytes(b: number): string {\n\tif (b >= 1024) return `${(b / 1024).toFixed(1)} KB`;\n\treturn `${b} B`;\n}\n\nfunction getResetsAtMs(errObj: Record<string, unknown>): number | null {\n\treturn (errObj.resetsAt as number | null) || (errObj.resets_at ? (errObj.resets_at as number) * 1000 : null);\n}\n\nfunction classifyStructuredError(errObj: Record<string, unknown>, resetsAt: number | null): ParsedError | null {\n\tif (!(errObj.title_key || errObj.detail_key)) return null;\n\tconst result = localizeStructuredError({\n\t\ticon: (errObj.icon as string) || \"\\u26A0\\uFE0F\",\n\t\ttitle: (errObj.title as string) || t(\"errors:generic.title\"),\n\t\tdetail: (errObj.detail as string) || (errObj.message as string) || \"\",\n\t\tprovider: errObj.provider as string | undefined,\n\t\tresetsAt: resetsAt,\n\t\ttitle_key: errObj.title_key as string | undefined,\n\t\tdetail_key: errObj.detail_key as string | undefined,\n\t\ttitle_params: errObj.title_params as Record<string, unknown> | undefined,\n\t\tdetail_params: errObj.detail_params as Record<string, unknown> | undefined,\n\t});\n\tif (!result) return null;\n\treturn {\n\t\ticon: result.icon || \"\\u26A0\\uFE0F\",\n\t\ttitle: result.title || t(\"errors:generic.title\"),\n\t\tdetail: result.detail || \"\",\n\t\tprovider: result.provider,\n\t\tresetsAt: result.resetsAt ?? null,\n\t};\n}\n\nfunction classifyUsageLimitError(errObj: Record<string, unknown>, resetsAt: number | null): ParsedError | null {\n\tif (\n\t\t!(errObj.type === \"usage_limit_reached\" || (errObj.message && String(errObj.message).indexOf(\"usage limit\") !== -1))\n\t) {\n\t\treturn null;\n\t}\n\treturn {\n\t\ticon: \"\",\n\t\ttitle: t(\"errors:usageLimitReached.title\"),\n\t\tdetail: t(\"errors:usageLimitReached.detail\", { planType: (errObj.plan_type as string) || \"current\" }),\n\t\tresetsAt: resetsAt,\n\t};\n}\n\nfunction classifyRateLimitError(errObj: Record<string, unknown>, resetsAt: number | null): ParsedError | null {\n\tif (\n\t\t!(errObj.type === \"rate_limit_exceeded\" || (errObj.message && String(errObj.message).indexOf(\"rate limit\") !== -1))\n\t) {\n\t\treturn null;\n\t}\n\treturn {\n\t\ticon: \"\\u26A0\\uFE0F\",\n\t\ttitle: t(\"errors:rateLimited.title\"),\n\t\tdetail: (errObj.message as string) || t(\"errors:rateLimited.detail\"),\n\t\tresetsAt: resetsAt,\n\t};\n}\n\nfunction classifyJsonErrorObj(errObj: Record<string, unknown>): ParsedError | null {\n\tconst resetsAt = getResetsAtMs(errObj);\n\treturn (\n\t\tclassifyStructuredError(errObj, resetsAt) ||\n\t\tclassifyUsageLimitError(errObj, resetsAt) ||\n\t\tclassifyRateLimitError(errObj, resetsAt) ||\n\t\t(errObj.message\n\t\t\t? { icon: \"\\u26A0\\uFE0F\", title: t(\"errors:generic.title\"), detail: errObj.message as string, resetsAt: null }\n\t\t\t: null)\n\t);\n}\n\nfunction parseJsonError(message: string): ParsedError | null {\n\tconst jsonMatch = message.match(/\\{[\\s\\S]*\\}$/);\n\tif (!jsonMatch) return null;\n\ttry {\n\t\tconst err = JSON.parse(jsonMatch[0]) as Record<string, unknown>;\n\t\treturn classifyJsonErrorObj((err.error as Record<string, unknown>) || err);\n\t} catch (_e) {\n\t\t/* fall through */\n\t}\n\treturn null;\n}\n\nfunction parseHttpStatusError(message: string): ParsedError | null {\n\tconst statusMatch = message.match(/HTTP (\\d{3})/);\n\tconst code = statusMatch ? parseInt(statusMatch[1], 10) : 0;\n\tif (code === 401 || code === 403)\n\t\treturn {\n\t\t\ticon: \"\\uD83D\\uDD12\",\n\t\t\ttitle: t(\"errors:authError.title\"),\n\t\t\tdetail: t(\"errors:authError.detail\"),\n\t\t\tresetsAt: null,\n\t\t};\n\tif (code === 429)\n\t\treturn {\n\t\t\ticon: \"\",\n\t\t\ttitle: t(\"errors:rateLimited.title\"),\n\t\t\tdetail: t(\"errors:rateLimited.detailShort\"),\n\t\t\tresetsAt: null,\n\t\t};\n\tif (code >= 500)\n\t\treturn {\n\t\t\ticon: \"\\uD83D\\uDEA8\",\n\t\t\ttitle: t(\"errors:serverError.title\"),\n\t\t\tdetail: t(\"errors:serverError.detail\"),\n\t\t\tresetsAt: null,\n\t\t};\n\treturn null;\n}\n\nexport function parseErrorMessage(message: string): ParsedError {\n\treturn (\n\t\tparseJsonError(message) ||\n\t\tparseHttpStatusError(message) || {\n\t\t\ticon: \"\\u26A0\\uFE0F\",\n\t\t\ttitle: t(\"errors:generic.title\"),\n\t\t\tdetail: message,\n\t\t\tresetsAt: null,\n\t\t}\n\t);\n}\n\nexport function updateCountdown(el: HTMLElement, resetsAtMs: number): boolean {\n\tconst now = Date.now();\n\tconst diff = resetsAtMs - now;\n\tif (diff <= 0) {\n\t\tel.textContent = t(\"errors:countdown.resetReady\");\n\t\tel.className = \"error-countdown reset-ready\";\n\t\treturn true;\n\t}\n\tconst hours = Math.floor(diff / 3600000);\n\tconst mins = Math.floor((diff % 3600000) / 60000);\n\tconst parts: string[] = [];\n\tif (hours > 0) parts.push(`${hours}h`);\n\tparts.push(`${mins}m`);\n\tel.textContent = t(\"errors:countdown.resetsIn\", { time: parts.join(\" \") });\n\treturn false;\n}\n\n/** Build a short summary string for a tool call card. */\nexport function toolCallSummary(\n\tname: string | undefined,\n\targs: ToolCallArgs | undefined,\n\texecutionMode?: string,\n): string {\n\tif (!args) return name || \"tool\";\n\tswitch (name) {\n\t\tcase \"exec\": {\n\t\t\tconst command = args.command || \"exec\";\n\t\t\tconst nodeRef = typeof args.node === \"string\" ? args.node.trim() : \"\";\n\t\t\tif (!nodeRef) return command;\n\t\t\tif (nodeRef.startsWith(\"ssh:target:\")) {\n\t\t\t\treturn `${command} [SSH target]`;\n\t\t\t}\n\t\t\tif (nodeRef.startsWith(\"ssh:\")) {\n\t\t\t\treturn `${command} [SSH: ${nodeRef.slice(4)}]`;\n\t\t\t}\n\t\t\tif (nodeRef.includes(\"@\")) {\n\t\t\t\treturn `${command} [SSH: ${nodeRef}]`;\n\t\t\t}\n\t\t\treturn `${command} [node: ${nodeRef}]`;\n\t\t}\n\t\tcase \"web_fetch\":\n\t\t\treturn `web_fetch ${args.url || \"\"}`.trim();\n\t\tcase \"web_search\":\n\t\t\treturn `web_search \"${args.query || \"\"}\"`;\n\t\tcase \"browser\": {\n\t\t\tconst action = args.action || \"browser\";\n\t\t\tconst mode = executionMode ? ` (${executionMode})` : \"\";\n\t\t\tconst url = args.url ? ` ${args.url}` : \"\";\n\t\t\treturn `browser ${action}${mode}${url}`.trim();\n\t\t}\n\t\tdefault:\n\t\t\treturn name || \"tool\";\n\t}\n}\n\n/**\n * Render a screenshot thumbnail with lightbox and download into `container`.\n * @param container - parent element to append into\n * @param imgSrc - image URL (data URI or HTTP URL)\n * @param scale - HiDPI scale factor\n */\nexport function renderScreenshot(container: HTMLElement, imgSrc: string, scale?: number): void {\n\tif (!scale) scale = 1;\n\tconst imgContainer = document.createElement(\"div\");\n\timgContainer.className = \"screenshot-container\";\n\tconst img = document.createElement(\"img\");\n\timg.src = imgSrc;\n\timg.className = \"screenshot-thumbnail\";\n\timg.alt = \"Browser screenshot\";\n\timg.title = \"Click to view full size\";\n\n\tconst effectiveScale = scale;\n\timg.onload = (): void => {\n\t\tif (effectiveScale > 1) {\n\t\t\tconst logicalWidth = img.naturalWidth / effectiveScale;\n\t\t\tconst logicalHeight = img.naturalHeight / effectiveScale;\n\t\t\timg.style.aspectRatio = `${logicalWidth} / ${logicalHeight}`;\n\t\t}\n\t};\n\n\tconst downloadScreenshot = (e: Event): void => {\n\t\te.stopPropagation();\n\t\tconst link = document.createElement(\"a\");\n\t\tlink.href = imgSrc;\n\t\tlink.download = `screenshot-${Date.now()}.png`;\n\t\tlink.click();\n\t};\n\n\timg.onclick = (): void => {\n\t\tconst overlay = document.createElement(\"div\");\n\t\toverlay.className = \"screenshot-lightbox\";\n\n\t\tconst lightboxContent = document.createElement(\"div\");\n\t\tlightboxContent.className = \"screenshot-lightbox-content\";\n\n\t\tconst header = document.createElement(\"div\");\n\t\theader.className = \"screenshot-lightbox-header\";\n\t\theader.onclick = (e: Event): void => e.stopPropagation();\n\n\t\tconst closeBtn = document.createElement(\"button\");\n\t\tcloseBtn.className = \"screenshot-lightbox-close\";\n\t\tcloseBtn.textContent = \"\\u2715\";\n\t\tcloseBtn.title = \"Close (Esc)\";\n\t\tcloseBtn.onclick = (): void => overlay.remove();\n\n\t\tconst downloadBtn = document.createElement(\"button\");\n\t\tdownloadBtn.className = \"screenshot-download-btn\";\n\t\tdownloadBtn.textContent = \"\\u2B07 Download\";\n\t\tdownloadBtn.onclick = downloadScreenshot;\n\n\t\theader.appendChild(closeBtn);\n\t\theader.appendChild(downloadBtn);\n\n\t\tconst scrollContainer = document.createElement(\"div\");\n\t\tscrollContainer.className = \"screenshot-lightbox-scroll\";\n\t\tscrollContainer.onclick = (e: Event): void => e.stopPropagation();\n\n\t\tconst fullImg = document.createElement(\"img\");\n\t\tfullImg.src = img.src;\n\t\tfullImg.className = \"screenshot-lightbox-img\";\n\n\t\tfullImg.onload = (): void => {\n\t\t\tconst logicalWidth = fullImg.naturalWidth / effectiveScale;\n\t\t\tconst logicalHeight = fullImg.naturalHeight / effectiveScale;\n\t\t\tconst viewportWidth = window.innerWidth - 80;\n\t\t\tconst displayWidth = Math.min(logicalWidth, viewportWidth);\n\t\t\tfullImg.style.width = `${displayWidth}px`;\n\t\t\tconst displayHeight = (displayWidth / logicalWidth) * logicalHeight;\n\t\t\tfullImg.style.height = `${displayHeight}px`;\n\t\t};\n\n\t\tscrollContainer.appendChild(fullImg);\n\t\tlightboxContent.appendChild(header);\n\t\tlightboxContent.appendChild(scrollContainer);\n\t\toverlay.appendChild(lightboxContent);\n\n\t\toverlay.onclick = (): void => overlay.remove();\n\t\tconst closeOnEscape = (e: KeyboardEvent): void => {\n\t\t\tif (e.key === \"Escape\") {\n\t\t\t\toverlay.remove();\n\t\t\t\tdocument.removeEventListener(\"keydown\", closeOnEscape);\n\t\t\t}\n\t\t};\n\t\tdocument.addEventListener(\"keydown\", closeOnEscape);\n\t\tdocument.body.appendChild(overlay);\n\t};\n\n\tconst thumbDownloadBtn = document.createElement(\"button\");\n\tthumbDownloadBtn.className = \"screenshot-download-btn-small\";\n\tthumbDownloadBtn.textContent = \"\\u2B07\";\n\tthumbDownloadBtn.title = \"Download screenshot\";\n\tthumbDownloadBtn.onclick = downloadScreenshot;\n\n\timgContainer.appendChild(img);\n\timgContainer.appendChild(thumbDownloadBtn);\n\tcontainer.appendChild(imgContainer);\n}\n\n// ── Document card ───────────────────────────────────────────\n\n/**\n * Return an icon string for a given MIME type / filename extension.\n */\nfunction documentIcon(mimeType?: string, filename?: string): string {\n\tconst ext = (filename || \"\").split(\".\").pop()?.toLowerCase() || \"\";\n\tif (mimeType === \"application/pdf\" || ext === \"pdf\") return \"\\uD83D\\uDCC4\"; // 📄\n\tif (mimeType === \"application/zip\" || mimeType === \"application/gzip\" || ext === \"zip\" || ext === \"gz\")\n\t\treturn \"\\uD83D\\uDCE6\"; // 📦\n\tif (/spreadsheet|csv|xls/.test(mimeType || \"\") || /^(csv|xls|xlsx)$/.test(ext)) return \"\\uD83D\\uDCCA\"; // 📊\n\tif (/wordprocessing|msword|rtf/.test(mimeType || \"\") || /^(doc|docx|rtf)$/.test(ext)) return \"\\uD83D\\uDCC3\"; // 📃\n\tif (/presentation|ppt/.test(mimeType || \"\") || /^(ppt|pptx)$/.test(ext)) return \"\\uD83D\\uDCCA\"; // 📊\n\treturn \"\\uD83D\\uDCC1\"; // 📁\n}\n\n/**\n * Format a byte count for display (e.g. \"1.2 MB\", \"345 KB\").\n */\nfunction formatDocSize(bytes: number): string {\n\tif (typeof bytes !== \"number\" || bytes < 0) return \"\";\n\tif (bytes >= 1048576) return `${(bytes / 1048576).toFixed(1)} MB`;\n\tif (bytes >= 1024) return `${(bytes / 1024).toFixed(1)} KB`;\n\treturn `${bytes} B`;\n}\n\n/**\n * Render a document card with filename, icon, and download link.\n * @param container - parent element to append into\n * @param mediaSrc - URL to the document (media API endpoint)\n * @param filename - display filename\n * @param mimeType - MIME type for icon selection\n * @param sizeBytes - file size for display\n */\nexport function renderDocument(\n\tcontainer: HTMLElement,\n\tmediaSrc: string,\n\tfilename: string,\n\tmimeType?: string,\n\tsizeBytes?: number,\n): void {\n\tconst wrap = document.createElement(\"div\");\n\twrap.className = \"document-container\";\n\n\tconst icon = document.createElement(\"span\");\n\ticon.className = \"document-icon\";\n\ticon.textContent = documentIcon(mimeType, filename);\n\n\tconst info = document.createElement(\"div\");\n\tinfo.className = \"document-info\";\n\n\tconst nameEl = document.createElement(\"span\");\n\tnameEl.className = \"document-filename\";\n\tnameEl.textContent = filename || \"document\";\n\n\tinfo.appendChild(nameEl);\n\n\tif (sizeBytes != null && sizeBytes > 0) {\n\t\tconst sizeEl = document.createElement(\"span\");\n\t\tsizeEl.className = \"document-size\";\n\t\tsizeEl.textContent = formatDocSize(sizeBytes);\n\t\tinfo.appendChild(sizeEl);\n\t}\n\n\tconst dlBtn = document.createElement(\"a\");\n\tdlBtn.className = \"document-download-btn\";\n\tdlBtn.href = mediaSrc;\n\tdlBtn.download = filename || \"document\";\n\t// PDFs and text open in new tab; others download\n\tconst isPdf = (mimeType || \"\").includes(\"pdf\") || (filename || \"\").endsWith(\".pdf\");\n\tconst isText = (mimeType || \"\").startsWith(\"text/\");\n\tif (isPdf || isText) {\n\t\tdlBtn.target = \"_blank\";\n\t\tdlBtn.rel = \"noopener noreferrer\";\n\t\tdlBtn.textContent = \"\\u2197 Open\";\n\t\tdlBtn.removeAttribute(\"download\");\n\t} else {\n\t\tdlBtn.textContent = \"\\u2B07 Download\";\n\t}\n\n\twrap.appendChild(icon);\n\twrap.appendChild(info);\n\twrap.appendChild(dlBtn);\n\tcontainer.appendChild(wrap);\n}\n\n// ── Waveform audio player ───────────────────────────────────\n\nconst WAVEFORM_BAR_COUNT = 48;\nconst WAVEFORM_MIN_HEIGHT = 0.08;\n\nasync function extractWaveform(audioSrc: string, barCount: number): Promise<number[]> {\n\tconst ctx = new (window.AudioContext || window.webkitAudioContext!)();\n\ttry {\n\t\tconst response = await fetch(audioSrc);\n\t\tconst buf = await response.arrayBuffer();\n\t\tconst audioBuffer = await ctx.decodeAudioData(buf);\n\t\tconst data = audioBuffer.getChannelData(0);\n\t\tif (data.length < barCount) {\n\t\t\treturn new Array(barCount).fill(WAVEFORM_MIN_HEIGHT) as number[];\n\t\t}\n\t\tconst step = Math.floor(data.length / barCount);\n\t\tconst peaks: number[] = [];\n\t\tfor (let i = 0; i < barCount; i++) {\n\t\t\tconst start = i * step;\n\t\t\tconst end = Math.min(start + step, data.length);\n\t\t\tlet max = 0;\n\t\t\tfor (let j = start; j < end; j++) {\n\t\t\t\tconst abs = Math.abs(data[j]);\n\t\t\t\tif (abs > max) max = abs;\n\t\t\t}\n\t\t\tpeaks.push(max);\n\t\t}\n\t\tlet maxPeak = 0;\n\t\tfor (const pk of peaks) {\n\t\t\tif (pk > maxPeak) maxPeak = pk;\n\t\t}\n\t\tmaxPeak = maxPeak || 1;\n\t\treturn peaks.map((v) => Math.max(WAVEFORM_MIN_HEIGHT, v / maxPeak));\n\t} finally {\n\t\tctx.close();\n\t}\n}\n\nexport function formatAudioDuration(seconds: number): string {\n\tif (!Number.isFinite(seconds) || seconds < 0) return \"00:00\";\n\tconst totalSeconds = Math.floor(seconds);\n\tconst m = Math.floor(totalSeconds / 60);\n\tconst s = totalSeconds % 60;\n\treturn `${String(m).padStart(2, \"0\")}:${String(s).padStart(2, \"0\")}`;\n}\n\nfunction createPlaySvg(): SVGSVGElement {\n\tconst NS = \"http://www.w3.org/2000/svg\";\n\tconst el = document.createElementNS(NS, \"svg\");\n\tel.setAttribute(\"viewBox\", \"0 0 24 24\");\n\tel.setAttribute(\"aria-hidden\", \"true\");\n\tel.setAttribute(\"focusable\", \"false\");\n\tel.setAttribute(\"fill\", \"currentColor\");\n\tel.setAttribute(\"preserveAspectRatio\", \"xMidYMid meet\");\n\n\tconst path = document.createElementNS(NS, \"path\");\n\tpath.setAttribute(\"d\", \"M8 5v14l11-7z\");\n\tel.appendChild(path);\n\treturn el;\n}\n\nfunction createPauseSvg(): SVGSVGElement {\n\tconst NS = \"http://www.w3.org/2000/svg\";\n\tconst el = document.createElementNS(NS, \"svg\");\n\tel.setAttribute(\"viewBox\", \"0 0 24 24\");\n\tel.setAttribute(\"aria-hidden\", \"true\");\n\tel.setAttribute(\"focusable\", \"false\");\n\tel.setAttribute(\"fill\", \"currentColor\");\n\tel.setAttribute(\"preserveAspectRatio\", \"xMidYMid meet\");\n\n\tconst left = document.createElementNS(NS, \"rect\");\n\tleft.setAttribute(\"x\", \"6\");\n\tleft.setAttribute(\"y\", \"4\");\n\tleft.setAttribute(\"width\", \"4\");\n\tleft.setAttribute(\"height\", \"16\");\n\tleft.setAttribute(\"rx\", \"1\");\n\tel.appendChild(left);\n\n\tconst right = document.createElementNS(NS, \"rect\");\n\tright.setAttribute(\"x\", \"14\");\n\tright.setAttribute(\"y\", \"4\");\n\tright.setAttribute(\"width\", \"4\");\n\tright.setAttribute(\"height\", \"16\");\n\tright.setAttribute(\"rx\", \"1\");\n\tel.appendChild(right);\n\treturn el;\n}\n\n// ── Audio autoplay unlock ────────────────────────────────────\n// Browsers block audio.play() without a recent user gesture. We \"unlock\"\n// playback by creating a shared AudioContext on the first user action\n// (sending a message / clicking record). Once resumed, all subsequent\n// audio.play() calls on the page are allowed.\nlet _audioCtx: AudioContext | null = null;\n\n/**\n * Call from a user-gesture handler (click / keydown) to unlock audio\n * playback for the current page session. Idempotent -- safe to call\n * multiple times.\n */\nexport function warmAudioPlayback(): void {\n\tif (!_audioCtx) {\n\t\t_audioCtx = new (window.AudioContext || window.webkitAudioContext!)();\n\t\tconsole.debug(\"[audio] created AudioContext, state:\", _audioCtx.state);\n\t}\n\tif (_audioCtx.state === \"suspended\") {\n\t\tconsole.debug(\"[audio] resuming suspended AudioContext\");\n\t\t_audioCtx.resume().catch((e: unknown) => console.warn(\"[audio] resume failed:\", e));\n\t}\n}\n\n/**\n * Render a waveform audio player (Telegram-style bars) into `container`.\n * @param container - parent element to append into\n * @param audioSrc - audio URL (HTTP or data URI)\n * @param autoplay - start playback immediately\n */\n// Track the most recently played audio element so spacebar can toggle it.\nlet _activeAudio: HTMLAudioElement | null = null;\n\nfunction isEditableTarget(el: EventTarget | null): boolean {\n\tif (!(el && el instanceof HTMLElement)) return false;\n\tconst tag = el.tagName;\n\tif (tag === \"INPUT\" || tag === \"TEXTAREA\" || tag === \"SELECT\") return true;\n\treturn el.isContentEditable;\n}\n\ndocument.addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\tif (e.key !== \" \" || e.repeat) return;\n\tif (isEditableTarget(e.target)) return;\n\tif (!_activeAudio) return;\n\te.preventDefault();\n\tif (_activeAudio.paused) {\n\t\t_activeAudio.play().catch(() => undefined);\n\t} else {\n\t\t_activeAudio.pause();\n\t}\n});\n\nexport function renderAudioPlayer(container: HTMLElement, audioSrc: string, autoplay?: boolean): void {\n\tconst wrap = document.createElement(\"div\");\n\twrap.className = \"waveform-player mt-2\";\n\n\tconst audio = document.createElement(\"audio\");\n\taudio.preload = \"auto\";\n\taudio.src = audioSrc;\n\n\tconst playBtn = document.createElement(\"button\");\n\tplayBtn.className = \"waveform-play-btn\";\n\tplayBtn.type = \"button\";\n\tplayBtn.appendChild(createPlaySvg());\n\n\tconst barsWrap = document.createElement(\"div\");\n\tbarsWrap.className = \"waveform-bars\";\n\n\tconst durEl = document.createElement(\"span\");\n\tdurEl.className = \"waveform-duration\";\n\tdurEl.textContent = \"00:00\";\n\n\twrap.appendChild(playBtn);\n\twrap.appendChild(barsWrap);\n\twrap.appendChild(durEl);\n\tcontainer.appendChild(wrap);\n\n\tconst bars: HTMLElement[] = [];\n\tfor (let i = 0; i < WAVEFORM_BAR_COUNT; i++) {\n\t\tconst bar = document.createElement(\"div\");\n\t\tbar.className = \"waveform-bar\";\n\t\tbar.style.height = \"20%\";\n\t\tbarsWrap.appendChild(bar);\n\t\tbars.push(bar);\n\t}\n\n\textractWaveform(audioSrc, WAVEFORM_BAR_COUNT)\n\t\t.then((peaks) => {\n\t\t\tpeaks.forEach((p, idx) => {\n\t\t\t\tbars[idx].style.height = `${p * 100}%`;\n\t\t\t});\n\t\t})\n\t\t.catch(() => {\n\t\t\tfor (const b of bars) {\n\t\t\t\tb.style.height = `${20 + Math.random() * 60}%`;\n\t\t\t}\n\t\t});\n\n\tfunction syncDurationLabel(): void {\n\t\tif (!Number.isFinite(audio.duration) || audio.duration < 0) return;\n\t\tdurEl.textContent = formatAudioDuration(audio.duration);\n\t}\n\n\taudio.addEventListener(\"loadedmetadata\", syncDurationLabel);\n\taudio.addEventListener(\"durationchange\", syncDurationLabel);\n\taudio.addEventListener(\"canplay\", syncDurationLabel);\n\n\tplayBtn.onclick = (): void => {\n\t\tif (audio.paused) {\n\t\t\taudio.play().catch(() => undefined);\n\t\t} else {\n\t\t\taudio.pause();\n\t\t}\n\t};\n\n\tlet rafId = 0;\n\tlet prevPlayed = -1;\n\n\tfunction tick(): void {\n\t\tif (!Number.isFinite(audio.duration) || audio.duration <= 0) {\n\t\t\trafId = requestAnimationFrame(tick);\n\t\t\treturn;\n\t\t}\n\t\tconst progress = audio.currentTime / audio.duration;\n\t\tconst playedCount = Math.floor(progress * WAVEFORM_BAR_COUNT);\n\t\tif (playedCount !== prevPlayed) {\n\t\t\tconst lo = Math.min(playedCount, prevPlayed < 0 ? 0 : prevPlayed);\n\t\t\tconst hi = Math.max(playedCount, prevPlayed < 0 ? WAVEFORM_BAR_COUNT : prevPlayed);\n\t\t\tfor (let idx = lo; idx < hi; idx++) {\n\t\t\t\tbars[idx].classList.toggle(\"played\", idx < playedCount);\n\t\t\t}\n\t\t\tprevPlayed = playedCount;\n\t\t}\n\t\tdurEl.textContent = formatAudioDuration(audio.currentTime);\n\t\trafId = requestAnimationFrame(tick);\n\t}\n\n\taudio.addEventListener(\"play\", () => {\n\t\t_activeAudio = audio;\n\t\tplayBtn.replaceChildren(createPauseSvg());\n\t\tprevPlayed = -1;\n\t\trafId = requestAnimationFrame(tick);\n\t});\n\n\taudio.addEventListener(\"pause\", () => {\n\t\tplayBtn.replaceChildren(createPlaySvg());\n\t\tcancelAnimationFrame(rafId);\n\t});\n\n\taudio.addEventListener(\"ended\", () => {\n\t\tif (_activeAudio === audio) _activeAudio = null;\n\t\tplayBtn.replaceChildren(createPlaySvg());\n\t\tcancelAnimationFrame(rafId);\n\t\tfor (const b of bars) b.classList.remove(\"played\");\n\t\tprevPlayed = -1;\n\t\tif (Number.isFinite(audio.duration) && audio.duration >= 0) {\n\t\t\tdurEl.textContent = formatAudioDuration(audio.duration);\n\t\t}\n\t});\n\n\tbarsWrap.onclick = (e: MouseEvent): void => {\n\t\tif (!Number.isFinite(audio.duration) || audio.duration <= 0) return;\n\t\tconst rect = barsWrap.getBoundingClientRect();\n\t\tconst fraction = (e.clientX - rect.left) / rect.width;\n\t\taudio.currentTime = Math.max(0, Math.min(1, fraction)) * audio.duration;\n\t\tif (audio.paused) audio.play().catch(() => undefined);\n\t};\n\n\tif (autoplay) {\n\t\t// Ensure AudioContext is resumed (may have been unlocked by warmAudioPlayback).\n\t\twarmAudioPlayback();\n\t\tconsole.debug(\n\t\t\t\"[audio] autoplay requested, readyState:\",\n\t\t\taudio.readyState,\n\t\t\t\"audioCtx:\",\n\t\t\t_audioCtx?.state,\n\t\t\t\"src:\",\n\t\t\taudioSrc.substring(0, 60),\n\t\t);\n\t\tconst doPlay = (): void => {\n\t\t\tconsole.debug(\"[audio] attempting play(), readyState:\", audio.readyState, \"paused:\", audio.paused);\n\t\t\taudio\n\t\t\t\t.play()\n\t\t\t\t.then(() => console.debug(\"[audio] play() succeeded\"))\n\t\t\t\t.catch((e: DOMException) => console.warn(\"[audio] play() rejected:\", e.name, e.message));\n\t\t};\n\t\t// Wait for enough data to be buffered before starting playback.\n\t\tif (audio.readyState >= 3) {\n\t\t\tdoPlay();\n\t\t} else {\n\t\t\tconsole.debug(\"[audio] waiting for canplay event\");\n\t\t\taudio.addEventListener(\"canplay\", doPlay, { once: true });\n\t\t}\n\t}\n}\n\n/**\n * Render a single clickable map link into `container`.\n * @param container - parent element to append into\n * @param links - map link payload\n * @param label - optional location label\n * @param heading - optional heading text\n */\nfunction resolveMapUrl(links: MapLinks | null | undefined): string {\n\tif (!(links && typeof links === \"object\")) return \"\";\n\tif (typeof links.url === \"string\" && links.url.trim()) return links.url.trim();\n\n\tconst providers: (keyof MapLinks)[] = [\"google_maps\", \"apple_maps\", \"openstreetmap\"];\n\tfor (const provider of providers) {\n\t\tconst providerUrl = links[provider];\n\t\tif (typeof providerUrl === \"string\" && providerUrl.trim()) return providerUrl.trim();\n\t}\n\treturn \"\";\n}\n\nfunction mapPointHeading(point: MapPoint, index: number): string {\n\tconst label = typeof point?.label === \"string\" ? point.label.trim() : \"\";\n\tif (label) return label;\n\tconst latOk = typeof point?.latitude === \"number\" && Number.isFinite(point.latitude);\n\tconst lonOk = typeof point?.longitude === \"number\" && Number.isFinite(point.longitude);\n\tif (latOk && lonOk) return `${point.latitude!.toFixed(5)}, ${point.longitude!.toFixed(5)}`;\n\treturn `Location ${index + 1}`;\n}\n\nfunction splitMapLinkText(text: string | undefined): { primary: string; secondary: string } {\n\tconst normalized = typeof text === \"string\" ? text.trim() : \"\";\n\tif (!normalized) return { primary: \"\", secondary: \"\" };\n\tconst starIndex = normalized.indexOf(\"\\u2B50\");\n\tif (starIndex <= 0) return { primary: normalized, secondary: \"\" };\n\tconst primary = normalized.slice(0, starIndex).trim();\n\tconst secondary = normalized.slice(starIndex).trim();\n\tif (!(primary && secondary)) return { primary: normalized, secondary: \"\" };\n\treturn { primary, secondary };\n}\n\nexport function renderMapLinks(\n\tcontainer: HTMLElement,\n\tlinks: MapLinks | null | undefined,\n\tlabel?: string,\n\theading?: string,\n): boolean {\n\tconst mapUrl = resolveMapUrl(links);\n\tif (!mapUrl) return false;\n\n\tconst block = document.createElement(\"div\");\n\tblock.className = \"mt-2\";\n\tconst text = heading || (typeof label === \"string\" && label.trim() ? label.trim() : \"Open map\");\n\tconst textParts = splitMapLinkText(text);\n\tconst link = document.createElement(\"a\");\n\tlink.href = mapUrl;\n\tlink.target = \"_blank\";\n\tlink.rel = \"noopener noreferrer\";\n\tlink.className = \"text-xs map-link-row\";\n\tconst primary = document.createElement(\"span\");\n\tprimary.className = \"map-link-name\";\n\tprimary.textContent = textParts.primary || text;\n\tlink.appendChild(primary);\n\tif (textParts.secondary) {\n\t\tconst secondary = document.createElement(\"span\");\n\t\tsecondary.className = \"map-link-meta\";\n\t\tsecondary.textContent = textParts.secondary;\n\t\tlink.appendChild(secondary);\n\t}\n\tlink.title = `Open \"${text}\" in maps`;\n\tblock.appendChild(link);\n\tcontainer.appendChild(block);\n\treturn true;\n}\n\nexport function renderMapPointGroups(\n\tcontainer: HTMLElement,\n\tpoints: MapPoint[] | null | undefined,\n\tfallbackLabel?: string,\n): boolean {\n\tif (!Array.isArray(points) || points.length === 0) return false;\n\n\tlet rendered = false;\n\tconst showHeadings = points.length > 1;\n\tfor (let i = 0; i < points.length; i++) {\n\t\tconst point = points[i];\n\t\tif (!(point && typeof point === \"object\")) continue;\n\t\tconst label = typeof point.label === \"string\" && point.label.trim() ? point.label.trim() : fallbackLabel;\n\t\tconst heading = showHeadings ? mapPointHeading(point, i) : \"\";\n\t\tif (renderMapLinks(container, point.map_links, label, heading)) rendered = true;\n\t}\n\treturn rendered;\n}\n\n/**\n * Parse the payload from `agents.list` into `{ defaultId, agents }`.\n * Handles both array (legacy) and object shapes.\n */\nexport function parseAgentsListPayload(payload: AgentEntry[] | AgentsListPayload): ParsedAgentsList {\n\tif (Array.isArray(payload)) {\n\t\tconst legacyDefault = payload.find((agent) => agent?.is_default === true && typeof agent?.id === \"string\")?.id;\n\t\treturn { defaultId: legacyDefault || \"main\", agents: payload };\n\t}\n\tconst agents = Array.isArray(payload?.agents) ? payload.agents : [];\n\tconst inferredDefault = agents.find((agent) => agent?.is_default === true && typeof agent?.id === \"string\")?.id;\n\treturn {\n\t\tdefaultId: typeof payload?.default_id === \"string\" ? payload.default_id : inferredDefault || \"main\",\n\t\tagents: agents,\n\t};\n}\n\nexport function createEl(tag: string, attrs?: CreateElAttrs | null, children?: (HTMLElement | null)[]): HTMLElemen